 12	    public static void main(String[] args) {
 13	        testBasicQueueOperations();
 14	        testWrapAroundBehavior();
 15	        testCapacityBoundaries();
 16	        testClearAndRemainingCapacity();
 17	        testIteratorTraversalAndFailFastBehavior();
 18	        testNullElementsAreRejected();
 19	
 20	        System.out.println("All CircularQueue tests passed.");
 21	    }
