 23	    private static void testBasicQueueOperations() {
 24	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 25	
 26	        queue.enqueue(10);
 27	        queue.enqueue(20);
 28	
 29	        assertEquals(2, queue.size(), "enqueue should increase the size");
 30	        assertEquals(1, queue.remainingCapacity(), "remaining capacity should decrease after enqueue");
 31	        assertEquals(Integer.valueOf(10), queue.peek(), "peek should return the front element");
 32	        assertEquals(Integer.valueOf(10), queue.peekFront(), "peekFront should return the front element");
 33	        assertEquals(Integer.valueOf(20), queue.peekRear(), "peekRear should return the rear element");
 34	        assertEquals(Integer.valueOf(10), queue.dequeue(), "dequeue should remove from the front");
 35	        assertEquals(Integer.valueOf(20), queue.poll(), "poll should remove and return the next element");
 36	        assertNull(queue.poll(), "poll should return null when the queue is empty");
 37	        assertThrows(IllegalStateException.class, queue::dequeue, "dequeue should throw when the queue is empty");
 38	    }
 39	
 40	    private static void testWrapAroundBehavior() {
 41	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 42	
 43	        queue.enqueue(1);
 44	        queue.enqueue(2);
 45	        queue.enqueue(3);
 46	        queue.dequeue();
 47	        queue.enqueue(4);
 48	
 49	        assertEquals("[2, 3, 4]", queue.toString(), "wrap-around should preserve iteration order");
 50	        assertEquals(Integer.valueOf(2), queue.peekFront(), "front should advance after dequeue");
 51	        assertEquals(Integer.valueOf(4), queue.peekRear(), "rear should track wrapped insertion");
 52	    }
 53	
 54	    private static void testCapacityBoundaries() {
 55	        CircularQueue<Integer> queue = new CircularQueue<>(2);
 56	
 57	        assertTrue(queue.offer(7), "offer should succeed when there is room");
 58	        assertTrue(queue.offer(8), "offer should succeed until the queue is full");
 59	        assertFalse(queue.offer(9), "offer should return false when the queue is full");
 60	        assertThrows(IllegalStateException.class, () -> queue.enqueue(9), "enqueue should throw when the queue is full");
 61	        assertEquals(0, queue.remainingCapacity(), "remaining capacity should be zero when full");
 62	    }
 63	
 64	    private static void testClearAndRemainingCapacity() {
 65	        CircularQueue<String> queue = new CircularQueue<>(2);
 66	
 67	        queue.enqueue("a");
 68	        queue.enqueue("b");
 69	        queue.clear();
 70	
 71	        assertTrue(queue.isEmpty(), "clear should empty the queue");
 72	        assertEquals(2, queue.remainingCapacity(), "clear should restore the full remaining capacity");
 73	        assertEquals("[]", queue.toString(), "clear should reset the string representation");
 74	    }
