 76	    private static void testIteratorTraversalAndFailFastBehavior() {
 77	        CircularQueue<Integer> queue = new CircularQueue<>(4);
 78	
 79	        queue.enqueue(5);
 80	        queue.enqueue(6);
 81	        queue.enqueue(7);
 82	
 83	        StringBuilder builder = new StringBuilder();
 84	        for (int value : queue) {
 85	            if (builder.length() > 0) {
 86	                builder.append(',');
 87	            }
 88	            builder.append(value);
 89	        }
 90	        assertEquals("5,6,7", builder.toString(), "iterator should traverse from head to tail");
 91	
 92	        Iterator<Integer> iterator = queue.iterator();
 93	        assertTrue(iterator.hasNext(), "iterator should have elements before mutation");
 94	        queue.dequeue();
 95	        assertThrows(
 96	                ConcurrentModificationException.class,
 97	                iterator::next,
 98	                "iterator should fail fast after queue mutation");
 99	    }
